widget.solution:
import math

def long_run_variance(omega, alpha, beta):
    if alpha + beta >= 1:
        raise ValueError("no long-run variance when alpha + beta >= 1")
    return omega / (1 - alpha - beta)

def long_run_annual_vol(omega, alpha, beta, pct=True):
    v = long_run_variance(omega, alpha, beta)
    vol = math.sqrt(252 * v)
    return vol / 100 if pct else vol

def variance_half_life(alpha, beta):
    p = alpha + beta
    if p >= 1:
        return math.inf
    return math.log(0.5) / math.log(p)
